  "inlineSchema": "// RelayPad - PostgreSQL provider schema (production).\n//\n// Model definitions are IDENTICAL to `prisma/schema.prisma` (SQLite dev) -\n// this file is DERIVED from it. Only the generator output directory and the\n// datasource differ:\n//\n//   provider = \"postgresql\"             production database\n//   url      = env(\"POSTGRES_DATABASE_URL\") a DEDICATED variable so the\n//                                        SQLite dev DATABASE_URL is never\n//                                        reused or clobbered.\n//   generator output = \"./generated-client\" the PostgreSQL client is\n//                                        generated into this folder and can\n//                                        NEVER overwrite the runtime SQLite\n//                                        client in node_modules/.prisma.\n//\n// Migrations for this provider live in `prisma/postgres/migrations` (Prisma\n// resolves the migrations folder relative to the schema file), so the SQLite\n// migration history under `prisma/migrations` is untouched. The baseline\n// migration there was generated by Prisma's PostgreSQL connector itself\n// (prisma migrate diff --from-empty --to-schema-datamodel) - it is NOT a\n// reinterpretation of the SQLite SQL.\n//\n// See docs/RELAY_OFFICIAL_PRODUCTION_READINESS.md section 4 for the full\n// strategy, verification status, and deployment steps.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"./generated-client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"POSTGRES_DATABASE_URL\")\n}\n\nenum LaunchRoute {\n  PUMP_PUMPSWAP\n  LAUNCHLAB_CPMM\n}\n\nenum LaunchStatus {\n  // Intent recorded, transaction not yet built or submitted.\n  PREPARATION\n  // Transaction submitted to RPC, confirmation pending.\n  SUBMITTED\n  // Transaction confirmed on-chain, mint verified.\n  CONFIRMED\n  // Confirmed and actively trading on the bonding curve.\n  CURVE_TRADING\n  // Graduation threshold crossed (observed on-chain).\n  GRADUATION_DETECTED\n  // Destination pool verified on-chain.\n  POOL_VERIFIED\n  // Transaction failed or was rejected; safe to retry.\n  FAILED\n  // Terminal unknown: submitted but confirmation could not be determined.\n  UNRESOLVED\n}\n\nmodel Launch {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  creatorWallet String\n  route         LaunchRoute\n  status        LaunchStatus @default(PREPARATION)\n\n  // Token metadata\n  name        String\n  symbol      String\n  description String?\n  metadataUri String?\n  imageUrl    String?\n  network     String // \"devnet\" | \"mainnet-beta\"\n\n  // On-chain identity (null until confirmed)\n  mintAddress    String?   @unique\n  signature      String?\n  slot           Int?\n  blockTime      DateTime?\n  // Idempotency key derived from client session + form data to prevent\n  // accidental duplicate submissions.\n  idempotencyKey String    @unique\n\n  // Destination pool (null until verified on-chain)\n  poolAddress    String?\n  poolVerifiedAt DateTime?\n\n  // Protocol-specific observed state (JSON snapshot from on-chain reads)\n  curveState Json?\n  lastError  String?\n\n  timeline LaunchEvent[]\n\n  @@index([creatorWallet, createdAt])\n  @@index([status])\n  @@index([route])\n}\n\n// Append-only lifecycle audit log. Idempotent via (launchId, kind, txOrSlotKey).\nmodel LaunchEvent {\n  id        String   @id @default(cuid())\n  launchId  String\n  launch    Launch   @relation(fields: [launchId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n  kind      String // e.g. \"submitted\", \"confirmed\", \"graduation_detected\", \"pool_verified\", \"failed\"\n  detail    Json?\n  // dedupe key: e.g. signature + kind, or slot + kind\n  dedupeKey String\n\n  @@unique([launchId, dedupeKey])\n  @@index([launchId])\n}\n\n// Audit log for metadata/artwork uploads (no credentials, no private data).\nmodel UploadAudit {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  uploader  String\n  fileName  String\n  sizeBytes Int\n  mime      String\n  cid       String?\n  status    String // \"ok\" | \"rejected\" | \"error\"\n  reason    String?\n}\n\n// =============================================================================\n// Official $RELAY treasury dashboard (read-only observability).\n//\n// On-chain state is the source of truth: every row below is derived from a\n// verified, confirmed transaction fetched over RPC and is idempotently\n// upserted (dedupe via (signature, entryKey)) so re-indexing never duplicates.\n// Public addresses and non-secret configuration only — no keys, ever.\n// =============================================================================\n\n// One verified on-chain activity entry relevant to a configured treasury wallet.\nmodel RelayOfficialActivity {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Transaction identity + dedupe. entryKey distinguishes multiple relevant\n  // entries inside one transaction (e.g. two transfers, or a swap + a burn).\n  signature String\n  entryKey  String\n\n  // Classification: \"fee_collect\" | \"transfer\" | \"swap\" | \"burn\" | \"other\"\n  type   String\n  status String // \"confirmed\" | \"failed\" — only confirmed rows are aggregated\n\n  slot       Int?\n  blockTime  DateTime?\n  // Which configured treasury wallet(s) this entry involves (role id: W1..W4).\n  walletRole String?\n\n  sender    String?\n  recipient String?\n\n  // Verified amounts. Stored as strings (u64-safe across providers).\n  inputAmount    String?\n  inputAsset     String? // mint address or \"SOL\"\n  inputDecimals  Int?\n  outputAmount   String?\n  outputAsset    String?\n  outputDecimals Int?\n\n  // For burns: the SPL mint actually burned + burn-instruction verification.\n  burnMint     String?\n  burnVerified Boolean @default(false)\n\n  // Owning program of the classified instruction (pump / pump-amm / system /\n  // spl-token / token-2022) — recorded, never guessed.\n  programId String?\n  network   String\n  detail    Json?\n\n  // Reconciliation: set once the signature is re-verified against the node.\n  onChainVerified Boolean   @default(false)\n  verifiedAt      DateTime?\n\n  @@unique([signature, entryKey])\n  @@index([type, blockTime])\n  @@index([signature])\n  @@index([walletRole, blockTime])\n  @@index([sender])\n  @@index([recipient])\n}\n\n// Per-scan indexing/reconciliation state (per configured wallet or global).\nmodel RelayOfficialIndexState {\n  id  String @id @default(cuid())\n  key String @unique // wallet address or \"reconcile\"\n\n  lastRunAt        DateTime?\n  lastStatus       String? // \"ok\" | \"error\"\n  lastError        String?\n  lastSignature    String?\n  // Last successful full reconciliation (DB rows re-checked against chain).\n  lastReconciledAt DateTime?\n}\n",
